import sys

def main():
    header = int(sys.stdin.readline().strip())
    operations = []

    for line in sys.stdin:
        line = line.strip()
        if line.startswith("Operation:"):
            operations.append(line[len("Operation:"):].strip())

    for op in operations:
        if op == "Toggle Packet Type":
            header ^= 1
            print(f"New Header in Decimal: {header}")
            print(f"New Header in Binary: {format(header, '08b')}")
        elif op == "Set Priority to High":
            header |= (1 << 1)
            print(f"New Header in Decimal: {header}")
            print(f"New Header in Binary: {format(header, '08b')}")
        elif op == "Clear Encryption Status":
            header &= ~(1 << 2)
            print(f"New Header in Decimal: {header}")
            print(f"New Header in Binary: {format(header, '08b')}")
        elif op == "Check if an error is detected":
            has_error = (header >> 3) & 1
            if has_error:
                print("Error Detected: Yes")
            else:
                print("Error Detected: No")
        elif op == "Shift the header left by 1 bit":
            header = header << 1
            if header > 255:
                header = header & 0xFF
            print(f"Header after Left Shift by 1 Bit: {header}")
            print(f"New Header in Binary: {format(header, '08b')}")

if __name__ == "__main__":
    main()
